content:
From 202e42e4aa890172366354b233c42c73107a3f59 Mon Sep 17 00:00:00 2001
From: Ilya Leoshkevich <iii@linux.ibm.com>
Date: Fri, 13 Mar 2026 18:46:25 +0100
Subject: [PATCH] s390/bpf: Zero-extend bpf prog return values and kfunc
 arguments

s390x ABI requires callers to zero-extend unsigned arguments and
sign-extend signed arguments, and callees to zero-extend unsigned
return values and sign-extend signed return values.

s390 BPF JIT currently implements only sign extension. Fix this
omission and implement zero extension too.

Fixes: 528eb2cb87bc ("s390/bpf: Implement arch_prepare_bpf_trampoline()")
Reported-by: Hari Bathini <hbathini@linux.ibm.com>
Closes: https://lore.kernel.org/bpf/20260312080113.843408-1-hbathini@linux.ibm.com/
Signed-off-by: Ilya Leoshkevich <iii@linux.ibm.com>
Tested-by: Ihor Solodrai <ihor.solodrai@linux.dev>
Link: https://lore.kernel.org/r/20260313174807.581826-1-iii@linux.ibm.com
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

diff --git a/arch/s390/net/bpf_jit_comp.c b/arch/s390/net/bpf_jit_comp.c
index 1f9a6b728beb..d08d159b6319 100644
--- a/arch/s390/net/bpf_jit_comp.c
+++ b/arch/s390/net/bpf_jit_comp.c
@@ -830,25 +830,34 @@ static int bpf_jit_probe_post(struct bpf_jit *jit, struct bpf_prog *fp,
 }

 /*
- * Sign-extend the register if necessary
+ * Sign- or zero-extend the register if necessary
  */
-static int sign_extend(struct bpf_jit *jit, int r, u8 size, u8 flags)
+static int sign_zero_extend(struct bpf_jit *jit, int r, u8 size, u8 flags)
 {
-	if (!(flags & BTF_FMODEL_SIGNED_ARG))
-		return 0;
-
 	switch (size) {
 	case 1:
-		/* lgbr %r,%r */
-		EMIT4(0xb9060000, r, r);
+		if (flags & BTF_FMODEL_SIGNED_ARG)
+			/* lgbr %r,%r */
+			EMIT4(0xb9060000, r, r);
+		else
+			/* llgcr %r,%r */
+			EMIT4(0xb9840000, r, r);
 		return 0;
 	case 2:
-		/* lghr %r,%r */
-		EMIT4(0xb9070000, r, r);
+		if (flags & BTF_FMODEL_SIGNED_ARG)
+			/* lghr %r,%r */
+			EMIT4(0xb9070000, r, r);
+		else
+			/* llghr %r,%r */
+			EMIT4(0xb9850000, r, r);
 		return 0;
 	case 4:
-		/* lgfr %r,%r */
-		EMIT4(0xb9140000, r, r);
+		if (flags & BTF_FMODEL_SIGNED_ARG)
+			/* lgfr %r,%r */
+			EMIT4(0xb9140000, r, r);
+		else
+			/* llgfr %r,%r */
+			EMIT4(0xb9160000, r, r);
 		return 0;
 	case 8:
 		return 0;
@@ -1798,9 +1807,9 @@ static noinline int bpf_jit_insn(struct bpf_jit *jit, struct bpf_prog *fp,
 				return -1;

 			for (j = 0; j < m->nr_args; j++) {
-				if (sign_extend(jit, BPF_REG_1 + j,
-						m->arg_size[j],
-						m->arg_flags[j]))
+				if (sign_zero_extend(jit, BPF_REG_1 + j,
+						     m->arg_size[j],
+						     m->arg_flags[j]))
 					return -1;
 			}
 		}
@@ -2566,7 +2575,7 @@ static int invoke_bpf_prog(struct bpf_tramp_jit *tjit,
 	EMIT6_PCREL_RILB_PTR(0xc0050000, REG_14, p->bpf_func);
 	/* stg %r2,retval_off(%r15) */
 	if (save_ret) {
-		if (sign_extend(jit, REG_2, m->ret_size, m->ret_flags))
+		if (sign_zero_extend(jit, REG_2, m->ret_size, m->ret_flags))
 			return -1;
 		EMIT6_DISP_LH(0xe3000000, 0x0024, REG_2, REG_0, REG_15,
 			      tjit->retval_off);
-- 
2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
s390/bpf: Zero-extend bpf prog return values and kfunc
 arguments

s390x ABI requires callers to zero-extend unsigned arguments and
sign-extend signed arguments, and callees to zero-extend unsigned
return values and sign-extend signed return values.

s390 BPF JIT currently implements only sign extension. Fix this
omission and implement zero extension too.

Fixes: 528eb2cb87bc ("s390/bpf: Implement arch_prepare_bpf_trampoline()")
Reported-by: Hari Bathini <hbathini@linux.ibm.com>
Closes: https://lore.kernel.org/bpf/20260312080113.843408-1-hbathini@linux.ibm.com/
Signed-off-by: Ilya Leoshkevich <iii@linux.ibm.com>
Tested-by: Ihor Solodrai <ihor.solodrai@linux.dev>
Link: https://lore.kernel.org/r/20260313174807.581826-1-iii@linux.ibm.com
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
The s390x ABI requires callers to zero-extend unsigned arguments and callees to zero-extend unsigned return values, but the BPF JIT compiler only implemented sign-extension (using instructions like lgbr, lghr, lgfr) for both signed and unsigned types. When the BTF function model flags indicated an unsigned argument or return value (i.e., BTF_FMODEL_SIGNED_ARG not set), the code incorrectly skipped extension entirely, violating the ABI and causing incorrect behavior for unsigned types.

Here is the patch:

 /*
- * Sign-extend the register if necessary
+ * Sign- or zero-extend the register if necessary
  */
-static int sign_extend(struct bpf_jit *jit, int r, u8 size, u8 flags)
+static int sign_zero_extend(struct bpf_jit *jit, int r, u8 size, u8 flags)
 {
-	if (!(flags & BTF_FMODEL_SIGNED_ARG))
-		return 0;
-
 	switch (size) {
 	case 1:
-		/* lgbr %r,%r */
-		EMIT4(0xb9060000, r, r);
+		if (flags & BTF_FMODEL_SIGNED_ARG)
+			/* lgbr %r,%r */
+			EMIT4(0xb9060000, r, r);
+		else
+			/* llgcr %r,%r */
+			EMIT4(0xb9840000, r, r);
 		return 0;
 	case 2:
-		/* lghr %r,%r */
-		EMIT4(0xb9070000, r, r);
+		if (flags & BTF_FMODEL_SIGNED_ARG)
+			/* lghr %r,%r */
+			EMIT4(0xb9070000, r, r);
+		else
+			/* llghr %r,%r */
+			EMIT4(0xb9850000, r, r);
 		return 0;
 	case 4:
-		/* lgfr %r,%r */
-		EMIT4(0xb9140000, r, r);
+		if (flags & BTF_FMODEL_SIGNED_ARG)
+			/* lgfr %r,%r */
+			EMIT4(0xb9140000, r, r);
+		else
+			/* llgfr %r,%r */
+			EMIT4(0xb9160000, r, r);
 		return 0;
 	case 8:
 		return 0;
 	default:
 		return -1;
 	}
 }

  */
 static noinline int bpf_jit_insn(struct bpf_jit *jit, struct bpf_prog *fp,
 				 int i, bool extra_pass)
 {
 	struct bpf_insn *insn = &fp->insnsi[i];
 	s32 branch_oc_off = insn->off;
 	u32 dst_reg = insn->dst_reg;
 	u32 src_reg = insn->src_reg;
 	struct bpf_jit_probe probe;
 	int last, insn_count = 1;
 	u32 *addrs = jit->addrs;
 	s32 imm = insn->imm;
 	s16 off = insn->off;
 	unsigned int mask;
 	int err;

 	bpf_jit_probe_init(&probe);

 	switch (insn->code) {
 	/*
 	 * BPF_MOV
 	 */
 	case BPF_ALU | BPF_MOV | BPF_X:
 		switch (insn->off) {
 		case 0: /* DST = (u32) SRC */
 			/* llgfr %dst,%src */
 			EMIT4(0xb9160000, dst_reg, src_reg);
 			if (insn_is_zext(&insn[1]))
 				insn_count = 2;
 			break;
 		case 8: /* DST = (u32)(s8) SRC */
 			/* lbr %dst,%src */
 			EMIT4(0xb9260000, dst_reg, src_reg);
 			/* llgfr %dst,%dst */
 			EMIT4(0xb9160000, dst_reg, dst_reg);
 			break;
 		case 16: /* DST = (u32)(s16) SRC */
 			/* lhr %dst,%src */
 			EMIT4(0xb9270000, dst_reg, src_reg);
 			/* llgfr %dst,%dst */
 			EMIT4(0xb9160000, dst_reg, dst_reg);
 			break;
 		}
 		break;
 	case BPF_ALU64 | BPF_MOV | BPF_X:
 		if (insn_is_cast_user(insn)) {
 			int patch_brc;

 			/* ltgr %dst,%src */
 			EMIT4(0xb9020000, dst_reg, src_reg);
 			/* brc 8,0f */
 			patch_brc = jit->prg;
 			EMIT4_PCREL_RIC(0xa7040000, 8, 0);
 			/* iihf %dst,user_arena>>32 */
 			EMIT6_IMM(0xc0080000, dst_reg, jit->user_arena >> 32);
 			/* 0: */
 			if (jit->prg_buf)
 				*(u16 *)(jit->prg_buf + patch_brc + 2) =
 					(jit->prg - patch_brc) >> 1;
 			break;
 		}
 		switch (insn->off) {
 		case 0: /* DST = SRC */
 			/* lgr %dst,%src */
 			EMIT4(0xb9040000, dst_reg, src_reg);
 			break;
 		case 8: /* DST = (s8) SRC */
 			/* lgbr %dst,%src */
 			EMIT4(0xb9060000, dst_reg, src_reg);
 			break;
 		case 16: /* DST = (s16) SRC */
 			/* lghr %dst,%src */
 			EMIT4(0xb9070000, dst_reg, src_reg);
 			break;
 		case 32: /* DST = (s32) SRC */
 			/* lgfr %dst,%src */
 			EMIT4(0xb9140000, dst_reg, src_reg);
 			break;
 		}
 		break;
 	case BPF_ALU | BPF_MOV | BPF_K: /* dst = (u32) imm */
 		/* llilf %dst,imm */
 		EMIT6_IMM(0xc00f0000, dst_reg, imm);
 		if (insn_is_zext(&insn[1]))
 			insn_count = 2;
 		break;
 	case BPF_ALU64 | BPF_MOV | BPF_K: /* dst = imm */
 		/* lgfi %dst,imm */
 		EMIT6_IMM(0xc0010000, dst_reg, imm);
 		break;
 	/*
 	 * BPF_LD 64
 	 */
 	case BPF_LD | BPF_IMM | BPF_DW: /* dst = (u64) imm */
 	{
 		/* 16 byte instruction that uses two 'struct bpf_insn' */
 		u64 imm64;

 		imm64 = (u64)(u32) insn[0].imm | ((u64)(u32) insn[1].imm) << 32;
 		/* lgrl %dst,imm */
 		EMIT6_PCREL_RILB(0xc4080000, dst_reg, _EMIT_CONST_U64(imm64));
 		insn_count = 2;
 		break;
 	}
 	/*
 	 * BPF_ADD
 	 */
 	case BPF_ALU | BPF_ADD | BPF_X: /* dst = (u32) dst + (u32) src */
 		/* ar %dst,%src */
 		EMIT2(0x1a00, dst_reg, src_reg);
 		EMIT_ZERO(dst_reg);
 		break;
 	case BPF_ALU64 | BPF_ADD | BPF_X: /* dst = dst + src */
 		/* agr %dst,%src */
 		EMIT4(0xb9080000, dst_reg, src_reg);
 		break;
 	case BPF_ALU | BPF_ADD | BPF_K: /* dst = (u32) dst + (u32) imm */
 		if (imm != 0) {
 			/* alfi %dst,imm */
 			EMIT6_IMM(0xc20b0000, dst_reg, imm);
 		}
 		EMIT_ZERO(dst_reg);
 		break;
 	case BPF_ALU64 | BPF_ADD | BPF_K: /* dst = dst + imm */
 		if (!imm)
 			break;
 		/* agfi %dst,imm */
 		EMIT6_IMM(0xc2080000, dst_reg, imm);
 		break;
 	/*
 	 * BPF_SUB
 	 */
 	case BPF_ALU | BPF_SUB | BPF_X: /* dst = (u32) dst - (u32) src */
 		/* sr %dst,%src */
 		EMIT2(0x1b00, dst_reg, src_reg);
 		EMIT_ZERO(dst_reg);
 		break;
 	case BPF_ALU64 | BPF_SUB | BPF_X: /* dst = dst - src */
 		/* sgr %dst,%src */
 		EMIT4(0xb9090000, dst_reg, src_reg);
 		break;
 	case BPF_ALU | BPF_SUB | BPF_K: /* dst = (u32) dst - (u32) imm */
 		if (imm != 0) {
 			/* alfi %dst,-imm */
 			EMIT6_IMM(0xc20b0000, dst_reg, -imm);
 		}
 		EMIT_ZERO(dst_reg);
 		break;
 	case BPF_ALU64 | BPF_SUB | BPF_K: /* dst = dst - imm */
 		if (!imm)
 			break;
 		if (imm == -0x80000000) {
 			/* algfi %dst,0x80000000 */
 			EMIT6_IMM(0xc20a0000, dst_reg, 0x80000000);
 		} else {
 			/* agfi %dst,-imm */
 			EMIT6_IMM(0xc2080000, dst_reg, -imm);
 		}
 		break;
 	/*
 	 * BPF_MUL
 	 */
 	case BPF_ALU | BPF_MUL | BPF_X: /* dst = (u32) dst * (u32) src */
 		/* msr %dst,%src */
 		EMIT4(0xb2520000, dst_reg, src_reg);
 		EMIT_ZERO(dst_reg);
 		break;
 	case BPF_ALU64 | BPF_MUL | BPF_X: /* dst = dst * src */
 		/* msgr %dst,%src */
 		EMIT4(0xb90c0000, dst_reg, src_reg);
 		break;
 	case BPF_ALU | BPF_MUL | BPF_K: /* dst = (u32) dst * (u32) imm */
 		if (imm != 1) {
 			/* msfi %r5,imm */
 			EMIT6_IMM(0xc2010000, dst_reg, imm);
 		}
 		EMIT_ZERO(dst_reg);
 		break;
 	case BPF_ALU64 | BPF_MUL | BPF_K: /* dst = dst * imm */
 		if (imm == 1)
 			break;
 		/* msgfi %dst,imm */
 		EMIT6_IMM(0xc2000000, dst_reg, imm);
 		break;
 	/*
 	 * BPF_DIV / BPF_MOD
 	 */
 	case BPF_ALU | BPF_DIV | BPF_X:
 	case BPF_ALU | BPF_MOD | BPF_X:
 	{
 		int rc_reg = BPF_OP(insn->code) == BPF_DIV ? REG_W1 : REG_W0;

 		switch (off) {
 		case 0: /* dst = (u32) dst {/,%} (u32) src */
 			/* xr %w0,%w0 */
 			EMIT2(0x1700, REG_W0, REG_W0);
 			/* lr %w1,%dst */
 			EMIT2(0x1800, REG_W1, dst_reg);
 			/* dlr %w0,%src */
 			EMIT4(0xb9970000, REG_W0, src_reg);
 			break;
 		case 1: /* dst = (u32) ((s32) dst {/,%} (s32) src) */
 			/* lgfr %r1,%dst */
 			EMIT4(0xb9140000, REG_W1, dst_reg);
 			/* dsgfr %r0,%src */
 			EMIT4(0xb91d0000, REG_W0, src_reg);
 			break;
 		}
 		/* llgfr %dst,%rc */
 		EMIT4(0xb9160000, dst_reg, rc_reg);
 		if (insn_is_zext(&insn[1]))
 			insn_count = 2;
 		break;
 	}
 	case BPF_ALU64 | BPF_DIV | BPF_X:
 	case BPF_ALU64 | BPF_MOD | BPF_X:
 	{
 		int rc_reg = BPF_OP(insn->code) == BPF_DIV ? REG_W1 : REG_W0;

 		switch (off) {
 		case 0: /* dst = dst {/,%} src */
 			/* lghi %w0,0 */
 			EMIT4_IMM(0xa7090000, REG_W0, 0);
 			/* lgr %w1,%dst */
 			EMIT4(0xb9040000, REG_W1, dst_reg);
 			/* dlgr %w0,%src */
 			EMIT4(0xb9870000, REG_W0, src_reg);
 			break;
 		case 1: /* dst = (s64) dst {/,%} (s64) src */
 			/* lgr %w1,%dst */
 			EMIT4(0xb9040000, REG_W1, dst_reg);
 			/* dsgr %w0,%src */
 			EMIT4(0xb90d0000, REG_W0, src_reg);
 			break;
 		}
 		/* lgr %dst,%rc */
 		EMIT4(0xb9040000, dst_reg, rc_reg);
 		break;
 	}
 	case BPF_ALU | BPF_DIV | BPF_K:
 	case BPF_ALU | BPF_MOD | BPF_K:
 	{
 		int rc_reg = BPF_OP(insn->code) == BPF_DIV ? REG_W1 : REG_W0;

 		if (imm == 1) {
 			if (BPF_OP(insn->code) == BPF_MOD)
 				/* lghi %dst,0 */
 				EMIT4_IMM(0xa7090000, dst_reg, 0);
 			else
 				EMIT_ZERO(dst_reg);
 			break;
 		}
 		if (!is_first_pass(jit) && can_use_ldisp_for_lit32(jit)) {
 			switch (off) {
 			case 0: /* dst = (u32) dst {/,%} (u32) imm */
 				/* xr %w0,%w0 */
 				EMIT2(0x1700, REG_W0, REG_W0);
 				/* lr %w1,%dst */
 				EMIT2(0x1800, REG_W1, dst_reg);
 				/* dl %w0,<d(imm)>(%l) */
 				EMIT6_DISP_LH(0xe3000000, 0x0097, REG_W0, REG_0,
 					      REG_L, EMIT_CONST_U32(imm));
 				break;
 			case 1: /* dst = (s32) dst {/,%} (s32) imm */
 				/* lgfr %r1,%dst */
 				EMIT4(0xb9140000, REG_W1, dst_reg);
 				/* dsgf %r0,<d(imm)>(%l) */
 				EMIT6_DISP_LH(0xe3000000, 0x001d, REG_W0, REG_0,
 					      REG_L, EMIT_CONST_U32(imm));
 				break;
 			}
 		} else {
 			switch (off) {
 			case 0: /* dst = (u32) dst {/,%} (u32) imm */
 				/* xr %w0,%w0 */
 				EMIT2(0x1700, REG_W0, REG_W0);
 				/* lr %w1,%dst */
 				EMIT2(0x1800, REG_W1, dst_reg);
 				/* lrl %dst,imm */
 				EMIT6_PCREL_RILB(0xc40d0000, dst_reg,
 						 _EMIT_CONST_U32(imm));
 				jit->seen |= SEEN_LITERAL;
 				/* dlr %w0,%dst */
 				EMIT4(0xb9970000, REG_W0, dst_reg);
 				break;
 			case 1: /* dst = (s32) dst {/,%} (s32) imm */
 				/* lgfr %w1,%dst */
 				EMIT4(0xb9140000, REG_W1, dst_reg);
 				/* lgfrl %dst,imm */
 				EMIT6_PCREL_RILB(0xc40c0000, dst_reg,
 						 _EMIT_CONST_U32(imm));
 				jit->seen |= SEEN_LITERAL;
 				/* dsgr %w0,%dst */
 				EMIT4(0xb90d0000, REG_W0, dst_reg);
 				break;
 			}
 		}
 		/* llgfr %dst,%rc */
 		EMIT4(0xb9160000, dst_reg, rc_reg);
 		if (insn_is_zext(&insn[1]))
 			insn_count = 2;
 		break;
 	}
 	case BPF_ALU64 | BPF_DIV | BPF_K:
 	case BPF_ALU64 | BPF_MOD | BPF_K:
 	{
 		int rc_reg = BPF_OP(insn->code) == BPF_DIV ? REG_W1 : REG_W0;

 		if (imm == 1) {
 			if (BPF_OP(insn->code) == BPF_MOD)
 				/* lhgi %dst,0 */
 				EMIT4_IMM(0xa7090000, dst_reg, 0);
 			break;
 		}
 		if (!is_first_pass(jit) && can_use_ldisp_for_lit64(jit)) {
 			switch (off) {
 			case 0: /* dst = dst {/,%} imm */
 				/* lghi %w0,0 */
 				EMIT4_IMM(0xa7090000, REG_W0, 0);
 				/* lgr %w1,%dst */
 				EMIT4(0xb9040000, REG_W1, dst_reg);
 				/* dlg %w0,<d(imm)>(%l) */
 				EMIT6_DISP_LH(0xe3000000, 0x0087, REG_W0, REG_0,
 					      REG_L, EMIT_CONST_U64(imm));
 				break;
 			case 1: /* dst = (s64) dst {/,%} (s64) imm */
 				/* lgr %w1,%dst */
 				EMIT4(0xb9040000, REG_W1, dst_reg);
 				/* dsg %w0,<d(imm)>(%l) */
 				EMIT6_DISP_LH(0xe3000000, 0x000d, REG_W0, REG_0,
 					      REG_L, EMIT_CONST_U64(imm));
 				break;
 			}
 		} else {
 			switch (off) {
 			case 0: /* dst = dst {/,%} imm */
 				/* lghi %w0,0 */
 				EMIT4_IMM(0xa7090000, REG_W0, 0);
 				/* lgr %w1,%dst */
 				EMIT4(0xb9040000, REG_W1, dst_reg);
 				/* lgrl %dst,imm */
 				EMIT6_PCREL_RILB(0xc4080000, dst_reg,
 						 _EMIT_CONST_U64(imm));
 				jit->seen |= SEEN_LITERAL;
 				/* dlgr %w0,%dst */
 				EMIT4(0xb9870000, REG_W0, dst_reg);
 				break;
 			case 1: /* dst = (s64) dst {/,%} (s64) imm */
 				/* lgr %w1,%dst */
 				EMIT4(0xb9040000, REG_W1, dst_reg);
 				/* lgrl %dst,imm */
 				EMIT6_PCREL_RILB(0xc4080000, dst_reg,
 						 _EMIT_CONST_U64(imm));
 				jit->seen |= SEEN_LITERAL;
